// Main.ts
import { ValidationPipe } from '@nestjs/common';
import { NestFactory } from '@nestjs/core';
import { DocumentBuilder, SwaggerModule } from '@nestjs/swagger';
import { AppModule } from '@/app.module';
import { AppLogger } from '@/common/logger/app-logger';
import { MssqlConfigurationService } from '@/config/database/mssql/abstract.mssql.config.service';
import { UrlApiConfigService } from '@/config/url-api/url-api.service';
import { MssqlDatabaseChecker } from '@/providers/database/mssql/mssql.database.checker';

/**
 *
 */
async function bootstrap(): Promise<void> {
  const app = await NestFactory.create(AppModule);
  app.useGlobalPipes(
    new ValidationPipe({
      forbidNonWhitelisted: true,
      transform: true,
      whitelist: true,
    }),
  );

  const { urlApi } = app.get(UrlApiConfigService);

  const config = new DocumentBuilder()
    .setTitle('master-api Swagger Documentation')
    .setDescription(
      "In this page you'll find all of the necessary informations about the microservice master-api  and it's different endpoints.",
    )
    .setVersion('1.0')
    .addServer(urlApi, 'pre-production')
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api', app, document);
  const databaseConfig = app.get(MssqlConfigurationService);
  const { migrationsWaitDelayMilliseconds, migrationsWaitRetryLimit } =
    databaseConfig;
  const logger = new AppLogger(bootstrap.name);
  const mssqlDatabaseChecker = app.get(MssqlDatabaseChecker);

  await mssqlDatabaseChecker.waitForMigrations(
    logger,
    migrationsWaitDelayMilliseconds,
    migrationsWaitRetryLimit,
  );

  await app.listen(3000);
}
bootstrap();

